	HERO_WIZARD_DESCRIPTION = "Các đại pháp sư dường như đều giống nhau: vẻ ngoài điên rồ nhưng trí tuệ sâu sắc. Phần lớn phép thuật đang được dạy ở học viện đều do Nivus sáng tạo. Sức mạnh phi thường đi cùng trách nhiệm nặng nề. Tự học nhưng có học trò khắp nơi, phép của ông khó đoán như những lời lảm nhảm. Nivus rất thận trọng, vì sức mạnh càng lớn, rắc rối càng nhiều. Chọc giận một pháp sư đã nguy hiểm, chọc giận một đại pháp sư còn tệ hơn… Chạy mau!",	
