	["I'm ready. Now bring it on!"] = "Tôi đã sẵn sàng. Bây giờ tiếp tục!",
	INAPP_DESCRIPTION_0001 = "Con trai xấu trong quả bom! Chỉ cần một người có thể làm sạch chiến trường, thu hoạch lợi nhuận càng tốt! Hãy nói cho chúng tôi biết bạn muốn ném nó đi đâu!",
	INAPP_DESCRIPTION_0002 = "Căng thế giới!\n\nBóng ma này có thể đóng băng tất cả những kẻ ác và ngăn chặn kẻ địch mới xuất hiện đến gần.",
	INAPP_DESCRIPTION_0003 = "Sử dụng những loại thuốc nổ đặc biệt này để ném kẻ địch thành mảnh vỡ.\n\nSức mạnh phá hủy được đảm bảo.",
