	INAPP_DESCRIPTION_0005 = "Màu đỏ bị mắc kẹt trong mặt nạ.\n\nĐánh giá về mặt nạ có thể mang lại 5 cuộc sống.",
	INAPP_DESCRIPTION_0006 = "Chuẩn bị kỹ luôn là điều quan trọng. Hãy mang thêm vàng ra trận!\n\nMỗi túi chứa 500 vàng.",
