	LEGAL_GOV_APPROVAL = "Bộ Văn hóa: Văn Tạng Đọc [2018] 0058 số %s",
	LEGAL_HEALTH_ADVICE = "Lời khuyên máu: chống lại trò chơi xấu, từ chối trò chơi cướp biển. Hãy cẩn thận với sự tự bảo vệ và tránh bị lừa đảo. Trò chơi trung bình, chơi bị thương. Đặt thời gian hợp lý, tận hưởng cuộc sống lành mạnh.",
	LEVEL_23_HEROIC = "Mô hình anh hùng mô tả 1",
	LEVEL_23_HISTORY = "Cảnh sát của Linirea!\nLại một lần nữa, chúng ta cần sự giúp đỡ của bạn, quân đội ác đang tấn công một lâu đài cổ được gọi là lâu đài chiến hàn! Nó đã không bị tấn công từ lâu. bây giờ nó lại bị bao vây bởi các bộ lạc thợ săn trong sa mạc!\n\nVua, bảo vệ chúng ta!",
	LEVEL_23_IRON = "Mô hình thép mô tả 1",
	LEVEL_23_IRON_UNLOCK = "Không có quân đội\nKhông thể tháp",
	LEVEL_23_MODES_UPGRADES = "Độ cao nhất 1\nKhông có anh hùng",
	LEVEL_23_TITLE = "Hammerhold",
	LEVEL_24_HEROIC = "Mô hình anh hùng mô tả 2",
	LEVEL_24_HISTORY = "Khi tình hình chiến tranh bị hỗn loạn, Vua Ma-la-gal đã lấy cắp củi từ lâu đài.\n\nCác nhà vệ sinh ở phía đông của chúng tôi cho biết, Malagall đang chạy trốn về phía đông, và lúc này, các nhà vệ sinh đang chống lại Vua Ma quỷ, kéo nó ra khỏi bước chạy trốn. - Thưa ông, chúng ta phải đi ngay, hỗ trợ!",
	LEVEL_24_IRON = "Mô hình thép mô tả 2",
	LEVEL_24_IRON_UNLOCK = "Không có quân đội\nKhông có súng",
	LEVEL_24_MODES_UPGRADES = "Độ cao nhất 2\nKhông có anh hùng",
	LEVEL_24_TITLE = "Sandhawk Hamlet",
	LEVEL_25_HEROIC = "Mô hình anh hùng mô tả 2",
	LEVEL_25_HISTORY = "Đội ngũ của chúng tôi đã kết thúc, chờ đợi sự ra đi của bạn. “Chúng ta phải đi qua sa mạc Azzar, tìm kiếm vua Ma-gà.”!\n\nSau những dấu vết của vua ma quỷ, chúng ta đi theo sa mạc Sapee, nơi chỉ có một vài nơi xanh trong sa mạc này. Tuy nhiên, các bộ lạc thợ săn trong sa mạc không thân thiện với những người đi qua, vì vậy đừng lo lắng về những người tồi tệ nhất trong sa mảnh – người Taksim!",
	LEVEL_25_IRON = "Mô hình thép mô tả 2",
	LEVEL_25_IRON_UNLOCK = "Không có súng",
	LEVEL_25_MODES_UPGRADES = "Độ cao nhất 2\nKhông có anh hùng",
	LEVEL_25_TITLE = "Sape Oasis",
	LEVEL_26_HEROIC = "Mô hình anh hùng mô tả 3",
	LEVEL_26_HISTORY = "Chiến tranh của Sapa Oaxaca dường như chỉ là một cuộc tấn công, và Ma-r-gal đã chạy trốn khỏi cỏ cướp biển cũ.\n\nKhông có lựa chọn nào, chỉ có thể vượt qua những ngọn đồi tuyệt vọng nguy hiểm. Không có thời gian để đi vòng quanh, cẩn thận với cát chảy dưới chân, nơi có một con quái vật bí ẩn, lấy mạng sống của vô số nhà thám hiểm có kinh nghiệm!",
	LEVEL_26_IRON = "Mô hình thép mô tả 3",
	LEVEL_26_IRON_UNLOCK = "Không có súng\nKhông thể tháp",
	LEVEL_26_MODES_UPGRADES = "Độ cao nhất 2\nKhông có anh hùng",
	LEVEL_26_TITLE = "Dunes of Despair",
	LEVEL_27_HEROIC = "Mô hình anh hùng mô tả 4",
	LEVEL_27_HISTORY = "Nhìn xem, đây là một con cướp biển!\nỞ đây có một nhóm các tên cướp biển và những tên cướm biển khốn khổ nhất thế giới, nhưng cũng có những người lính tốt nhất thế giới có thể đưa bạn qua biển tinh thể.\n\nKhi hỏi bạn bè trên đường đen, chúng tôi biết rằng vua Ma-gál đã chạy trốn bằng thuyền đến cửa Nazarou. Hãy thuê một thuyền viên, nhưng trước tiên phải chờ đợi, đội quân của kẻ địch đã đến gần chúng ta. ↓ ↓!",
	LEVEL_27_IRON = "Mô hình thép mô tả 4",
	LEVEL_27_IRON_UNLOCK = "Không quân trại\nKhông có súng",
	LEVEL_27_MODES_UPGRADES = "Độ cao nhất 2",
	LEVEL_27_TITLE = "Buccaneer's Den",
	LEVEL_28_HEROIC = "Mô hình anh hùng mô tả 5",
	LEVEL_28_HISTORY = "Đến trước cửa Nazarou huyền thoại, nó chặn đường duy nhất đến nơi mất tích. Nơi này hơi không ổn, quân đội rất căng thẳng. Không phải vì kẻ địch mà chúng ta gặp, mà vì kẻ địch chúng ta gặp phải.\n\nMay mắn thay, các công ty của Dafa đã đến và giúp chúng tôi mở cửa. Nếu chiến đấu bùng nổ, họ cũng sẽ giúp chúng ta một cánh tay.",
	LEVEL_28_IRON = "Mô hình thép mô tả 5",
	LEVEL_28_IRON_UNLOCK = "Không quân trại\nKhông có quân đội",
	LEVEL_28_MODES_UPGRADES = "Độ cao nhất 3",
	LEVEL_28_TITLE = "Nazeru's Gates",
	LEVEL_29_HEROIC = "Mô hình anh hùng mô tả 6",
	LEVEL_29_HISTORY = "Khi chúng tôi đến thung lũng Đỏ, một nhóm thờ phượng mạnh mẽ đã tham gia chúng tôi. Vịnh Đỏ là một khu săn mồi của người Macwans, vì nó được đặt tên là. Họ quyết định xây dựng trại ở đây, chỉ cho mọi người nghỉ ngơi, nhưng cũng không thể thư giãn.\n\nKhông ai gặp người Macau, nhưng một số tin đồn về người Macau là rất khó chịu.",
	LEVEL_29_IRON = "Mô hình thép mô tả 6",
	LEVEL_29_IRON_UNLOCK = "Không có súng\nKhông có quân đội",
	LEVEL_29_MODES_UPGRADES = "Độ cao nhất 3",
	LEVEL_29_TITLE = "Crimson Valley",
	LEVEL_2_MODE_CAMPAIGN = "Chiến dịch",
	LEVEL_2_MODE_HEROIC = "Thử thách Anh hùng",
	LEVEL_2_MODE_HEROIC_DESCRIPTION = "Thử thách dành cho những người phòng thủ anh dũng nhất. Hãy kiểm chứng tài thao lược trước lực lượng tinh nhuệ của kẻ địch!",
	LEVEL_2_MODE_IRON = "Thử thách Sắt",
	LEVEL_2_MODE_IRON_DESCRIPTION = "Thử thách Sắt dành cho người phòng thủ xuất sắc, đẩy kỹ năng chiến thuật của bạn đến giới hạn.",
	LEVEL_2_MODE_LOCKED_DESCRIPTION = "Hoàn thành màn này với 3 sao để mở khóa chế độ.",
