	LEVEL_2_SELECT_TO_BATTLE = "Vào\ntrận",
	LEVEL_30_HEROIC = "Mô hình anh hùng mô tả 7",
	LEVEL_30_HISTORY = "Các lực lượng phía trước đã báo cáo rằng Vua Ma-la-gal đang chạy về phía đông đến thành phố McValk, phía bên kia sông Zaglon. Đi qua sông Zaglon là qua “cây cầu”. Cầu này được xây dựng từ lâu bởi đội khám phá Barlington-Kinnes.\n\nCác đồng minh mới của chúng tôi là kẻ địch của người Macau, họ đã cảnh báo chúng tôi về một số điều liên quan đến thực vật. dường như có một cái gì đó đặc biệt hấp dẫn ở gần đó.",
	LEVEL_30_IRON = "Mô hình thép mô tả 7",
	LEVEL_30_IRON_UNLOCK = "Không thể tháp\nKhông có súng",
	LEVEL_30_MODES_UPGRADES = "Độ cao nhất 3",
	LEVEL_30_TITLE = "Snapvine Bridge",
	LEVEL_31_HEROIC = "Mô hình anh hùng mô tả 8",
	LEVEL_31_HISTORY = "Khi đi đến thành phố Macvalco, rừng ngày càng nguy hiểm. Mùa giải này, bao gồm những cây rễ, cây rễ và cây rễ dường như chưa bao giờ cảm nhận được sự ấm áp của ánh nắng mặt trời, và một cái gì đó tối tăm hơn đang lặn trong rừng mưa.\n\nMọi người có cảm giác như thể họ đang bị đuổi theo một thứ không thuộc về thế giới này. thậm chí cả những người đã chết cũng lo lắng. Tuy nhiên, kế hoạch chống lại Vua Ma-gall chỉ thúc đẩy chúng ta dừng lại càng sớm càng tốt.",
	LEVEL_31_IRON = "Mô hình thép mô tả 8",
	LEVEL_31_IRON_UNLOCK = "Không quân trại\nKhông thể tháp",
	LEVEL_31_MODES_UPGRADES = "Độ cao nhất 4",
	LEVEL_31_TITLE = "Lost Jungle",
	LEVEL_32_HEROIC = "Mô hình anh hùng mô tả 9",
	LEVEL_32_HISTORY = "Cái gì ở phía trước là thành phố Macval. Thành phố cổ này là ngôi nhà của kẻ địch của chúng ta – ngôi nhà của bộ lạc người Macva ác. Từ tai nghe tiếng động đất trên núi và tiếng ma thuật thấp, gặp mặt những sóng nóng rực rỡ rỡ của núi lửa nguy hiểm. Đây là trụ sở của Macau!\n\nĐối với kẻ địch khủng khiếp của chúng ta, chúng ta phải phá vỡ quân đội của người Macau ở xung quanh thành phố. Tuy nhiên, các kỹ sư và kỹ sư của chúng tôi đã chuẩn bị cho chúng tôi một phép lạ cơ học khổng lồ.",
	LEVEL_32_IRON = "Mô hình thép mô tả 9",
	LEVEL_32_IRON_UNLOCK = "Không có súng\nKhông thể tháp",
	LEVEL_32_MODES_UPGRADES = "Độ cao nhất 4",
	LEVEL_32_TITLE = "Ma'qwa Urqu",
	LEVEL_33_HEROIC = "Mô hình anh hùng mô tả 10",
	LEVEL_33_HISTORY = "Tôi đã bao quanh anh ta! Đền Sakura là nơi chôn vùi của vua Malagall! Các người Macva đang trở nên điên rồ hơn, đây là nơi thánh của họ để thờ phượng thần crocodile, bây giờ được dẫn dắt bởi vua của các cổng quân sự.\n\nSự kết hợp của người Macva với vua của các cổng quân sự trở nên vô cùng mạnh mẽ, và trở thành một trong những quân đội ác đáng sợ nhất từng có. Hãy hết sức mình, hãy chiến đấu, anh em, nếu không chúng ta sẽ là những phần của Sakura. hoặc tệ hơn nữa.",
	LEVEL_33_IRON = "Mô hình thép mô tả 10",
	LEVEL_33_IRON_UNLOCK = "Không quân trại\nKhông có quân đội",
	LEVEL_33_MODES_UPGRADES = "Độ cao nhất 4",
	LEVEL_33_TITLE = "Temple of Saqra",
	LEVEL_34_HEROIC = "Mô hình anh hùng mô tả 11",
	LEVEL_34_HISTORY = "Đền Sakura chỉ có vẻ như là một lối vào một nhà thờ sâu thẳm khổng lồ được đào trực tiếp trên đá! Có những câu chuyện truyền thuyết cảnh báo chúng ta rằng có một cái ác khó hiểu ở đây, có lẽ sự thật ở bên trong.\n\nTôi phải đi sâu vào mê cung, không thể rời đi nửa đường. Nếu chúng ta chỉ có cái bóng tối vô tận này, thì đó là tin tốt.",
	LEVEL_34_IRON = "Mô hình thép mô tả 11",
	LEVEL_34_IRON_UNLOCK = "Không có súng\nKhông thể tháp",
	LEVEL_34_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_34_TITLE = "The Underpass",
	LEVEL_35_HEROIC = "Mô hình anh hùng mô tả 12",
	LEVEL_35_HISTORY = "Đã có vài ngày chúng ta đang đi bộ trong mê cung đá này, nhưng không tìm thấy bất kỳ dấu vết nào của kẻ địch. cho đến khi chúng ta chỉ có thể tìm thấy dấu vết của kẻ địch, nhưng chúng ta càng sâu hơn, chúng ta càng nóng hơn!\n\nCác câu chuyện cổ trên tường nói với chúng ta rằng chúng ta đang tiến về phía Hall of Belize, và nếu truyền thuyết là đúng, chúng ta có thể bị \"cảm xúc\" đón nhận.",
	LEVEL_35_IRON = "Mô hình thép mô tả 12",
	LEVEL_35_IRON_UNLOCK = "Không thể tháp\nKhông có quân đội",
	LEVEL_35_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_35_TITLE = "Beresad's Lair",
	LEVEL_36_HEROIC = "Mô hình anh hùng mô tả 13",
	LEVEL_36_HISTORY = "Cung cấp của chúng tôi sắp hết hạn, đạo đức cũng thấp đến thung lũng, một số người chỉ chạy trốn. May mắn thay, chúng tôi gặp một nhóm người thỏ, họ đào quá sâu trong đường, chỉ cần chặn đường, ngăn chặn người thỏ.\n\nHọ hứa sẽ tham gia chúng tôi và tìm ra con đường ra khỏi nơi này. Tuy nhiên, việc chạy trốn phải được giải quyết trước, chúng ta và các đồng minh mới phải đối mặt trước với quân đội phun-đã gần!",
	LEVEL_36_IRON = "Mô hình thép mô tả 13",
	LEVEL_36_IRON_UNLOCK = "Không có súng\nKhông quân trại",
	LEVEL_36_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_36_TITLE = "The Dark Descent",
	LEVEL_37_HEROIC = "Mô hình anh hùng mô tả 14",
	LEVEL_37_HISTORY = "Cuối cùng! Chiến tranh với Vua và quân đội của ông sắp đến! Lễ hội tối tăm đang giải phóng chủ nhân ác của vua ma! Con số của cả thế giới sẽ nằm trên vai anh.\n\nĐất nước sa mạc, xa biên giới, chín đời chết, là ví dụ điển hình và chiến thuật xuất sắc của bạn đưa chúng ta đến đây. Chỉ có bạn mới có thể hoàn thành nhiệm vụ khó khăn này, tiêu diệt kẻ địch. Đối với Linirea!",
	LEVEL_37_IRON = "Mô hình thép mô tả 14",
	LEVEL_37_IRON_UNLOCK = "Không thể tháp",
	LEVEL_37_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_37_TITLE = "Emberspike Depths",
	LEVEL_38_HEROIC = "Mô hình anh hùng mô tả 16",
	LEVEL_38_HISTORY = "Vào những tuần qua, những sự cố lạ lùng khiến cả người biển và người cá đều bắt đầu cảnh giác. Các báo cáo cho biết, tàu và người dân đã biến mất bí ẩn trong vùng biển gần đó, và họ đã mất tích. Các lực lượng hải quân của chúng tôi ở đảo Cướp biển yêu cầu sự giúp đỡ của chúng tôi.\n\nHiện chưa chắc chắn ai là người hay cái gì đang đâm đồn sau sự cố này, nhưng tình hình của làng biển của chúng tôi rất nguy hiểm, và vua cho phép bạn dẫn dắt một đội tàu tấn công nhỏ, điều tra mối đe dọa mới xuất hiện này.",
	LEVEL_38_IRON = "Mô hình thép mô tả 16",
	LEVEL_38_IRON_UNLOCK = "Không thể tháp\nKhông có súng",
	LEVEL_38_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_38_TITLE = "Port Tortuga",
	LEVEL_39_HEROIC = "Mô hình anh hùng mô tả 16",
	LEVEL_39_HISTORY = "Cẩn thận với quỷ sâu! Tôi tin rằng những con quỷ tàn bạo này đã bị hủy diệt bởi Hải quân Vương quốc và Cục Anh em Cướp biển của Linirea cách đây vài thập kỷ. Tại cảng bọ chét, dưới những sinh vật xấu xa như nước lụt liên tục chúng ta gần như bị chìm, bây giờ phải leo lên bờ biển trong bão bão bốn lần.\n\nỞ đây chúng ta phải chuẩn bị chiến đấu, gần đó là Thượng Đế của đại dương – những phần còn lại của đền thờ của Thượng Đàng. Hãy cầu nguyện cho Đức Giê-hô-va, xin Ngài ban ân sủng cho người bảo vệ của Lên-vi-a!",
	LEVEL_39_IRON = "Mô hình thép mô tả 16",
	LEVEL_39_IRON_UNLOCK = "Không có quân đội\nKhông có súng",
	LEVEL_39_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_39_TITLE = "Storm Atoll",
	LEVEL_40_HEROIC = "Mô hình anh hùng mô tả 18",
	LEVEL_40_HISTORY = "Với sự bảo vệ của Thượng Đế, chúng ta đã giành chiến thắng trong cuộc chiến! Tuy nhiên, những người cười đến cuối cùng vẫn có thể là quỷ sâu, vì họ đã làm tỉnh lại Levitane - một vị thần ác mà họ tôn thờ. Nếu Levitine có được sức mạnh hoàn toàn, không có gì trên thế giới có thể ngăn chặn nó.\n\nKhông thể sửa chữa lại đội và nghỉ ngơi, chúng tôi đi thẳng vào cái mảnh của Levitane. Đó là thành phố cổ của Liliê, nơi mà vị thần của đại dương đã cai trị. Đã đến lúc tiêu diệt hoàn toàn các quỷ và thần ác của họ!",
	LEVEL_40_IRON = "Mô hình thép mô tả 18",
	LEVEL_40_IRON_UNLOCK = "Không có quân đội\nKhông quân trại",
	LEVEL_40_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_40_TITLE = "The Sunken Citadel",
	LEVEL_41_HEROIC = "Mô hình anh hùng mô tả 15",
	LEVEL_41_HISTORY = "Đêm tối vô tận đến! Một điều ác đã được thức dậy, khiến toàn bộ khu vực rơi vào bóng tối! Quỷ không có suy nghĩ đang lặn quanh trái đất, ăn thịt người!\n\nVua của chúng tôi sẽ giết bạn để bảo vệ những người dân làng không có tay và tìm ra nguồn gốc của thảm họa này. Vương quốc cần bạn!",
	LEVEL_41_IRON = "Mô hình thép mô tả 15",
	LEVEL_41_IRON_UNLOCK = "Không quân trại\nKhông thể tháp",
	LEVEL_41_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_41_TITLE = "Bonesburg",
	LEVEL_42_HEROIC = "Mô hình anh hùng mô tả 15",
	LEVEL_42_HISTORY = "Sau khi giải phóng thành phố trắng, chúng tôi đi theo những điều ác đến một khu rừng kỳ lạ. Bạn có thể cảm nhận được sự dữ dội phát triển trong rừng không? Cây xấu xa lạ lùng bao phủ các mảnh tối. Đây là buổi lễ cấm. Quỷ Đen đang lặn trong bóng tối, cuộc chiến bắt đầu!",
	LEVEL_42_IRON = "Mô hình thép mô tả 15",
	LEVEL_42_IRON_UNLOCK = "Không có súng\nKhông thể tháp",
	LEVEL_42_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_42_TITLE = "Desecrated Grove",
	LEVEL_43_HEROIC = "Mô hình anh hùng mô tả 15",
	LEVEL_43_HISTORY = "Ở trong khu vực tối tăm nhất của rừng, chúng ta tìm thấy nguồn gốc của sự dữ. Vasile thức dậy từ giấc ngủ dài! Vasile lại thể hiện sức mạnh tối tăm của mình! Vasile, một hoàng tử ma cà rồng lâu đời, đã lâu rồi mọi người nghĩ rằng anh ta không còn tồn tại nữa!\n\nĐội ác cũ này đang thống nhất quân đội tối của mình trong nhà, muốn biến quân đội của bạn thành một đội quân ma cà rồng, để phục vụ nó. Hãy để ánh sáng sáng lên bóng tối này, để kết thúc đêm đen dài này. cho Linirea!",
	LEVEL_43_IRON = "Mô hình thép mô tả 15",
	LEVEL_43_IRON_UNLOCK = "Không có quân đội\nKhông quân trại",
	LEVEL_43_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_43_TITLE = "Dusk Chateau",
	LEVEL_44_HEROIC = "Mô hình anh hùng mô tả 15",
	LEVEL_44_HISTORY = "Các con rắn là đồng minh mạnh nhất của chúng ta, và vua của chúng ta đã đặt chúng vào vị trí bảo vệ hang. Khi họ tìm kiếm Vương quốc Loriya bị mất, họ đã tìm thấy một mạng lưới đường hầm bí mật của người Hồi giáo.\n\nVới những đường hầm này, một đội quân khổng lồ của người Feng Shui có thể đi đến bề mặt và chiếm được Linirea dưới sự lãnh đạo của Thượng Shui. Bạn phải tham gia vào đội của những con rắn để ngăn chặn Sitz và những con quái vật của nó. Chỉ có Dinnas là vua của Linirea!",
	LEVEL_44_IRON = "Mô hình thép mô tả 15",
	LEVEL_44_IRON_UNLOCK = "Không quân trại\nKhông thể tháp",
	LEVEL_44_MODES_UPGRADES = "Độ cao nhất 5",
	LEVEL_44_TITLE = "Darklight Depths",
	["Let's hurry up. I want to go back to camp."] = "Chúng ta nhanh đi. Tôi muốn trở về trại.",
	Level = "Tỷ lệ",
	["Like yesterday… and the day before…"] = "Như ngày hôm qua, cũng như ngày trước.",
